#!/bin/bash

# Script to fix Swift 6 'weak let' issues in expo-modules-jsi
# Run this from your project root directory

BASE_PATH="node_modules/expo-modules-jsi/apple/Sources/ExpoModulesJSI"

echo "Fixing Swift 6 compatibility issues in expo-modules-jsi..."

# Fix HostObjectContext.swift
if [ -f "$BASE_PATH/Contexts/HostObjectContext.swift" ]; then
  echo "Fixing HostObjectContext.swift..."
  sed -i '' 's/weak let runtime: JavaScriptRuntime?/weak var runtime: JavaScriptRuntime?/g' "$BASE_PATH/Contexts/HostObjectContext.swift"
fi

# Fix JavaScriptActor.swift (has two occurrences)
if [ -f "$BASE_PATH/Runtime/JavaScriptActor.swift" ]; then
  echo "Fixing JavaScriptActor.swift..."
  sed -i '' 's/weak let runtime: JavaScriptRuntime?/weak var runtime: JavaScriptRuntime?/g' "$BASE_PATH/Runtime/JavaScriptActor.swift"
fi

# Fix JavaScriptArray.swift
if [ -f "$BASE_PATH/Runtime/Values/JavaScriptArray.swift" ]; then
  echo "Fixing JavaScriptArray.swift..."
  sed -i '' 's/private weak let runtime: JavaScriptRuntime?/private weak var runtime: JavaScriptRuntime?/g' "$BASE_PATH/Runtime/Values/JavaScriptArray.swift"
fi

# Fix JavaScriptArrayBuffer.swift
if [ -f "$BASE_PATH/Runtime/Values/JavaScriptArrayBuffer.swift" ]; then
  echo "Fixing JavaScriptArrayBuffer.swift..."
  sed -i '' 's/private weak let runtime: JavaScriptRuntime?/private weak var runtime: JavaScriptRuntime?/g' "$BASE_PATH/Runtime/Values/JavaScriptArrayBuffer.swift"
fi

# Fix JavaScriptBigInt.swift
if [ -f "$BASE_PATH/Runtime/Values/JavaScriptBigInt.swift" ]; then
  echo "Fixing JavaScriptBigInt.swift..."
  sed -i '' 's/private weak let runtime: JavaScriptRuntime?/private weak var runtime: JavaScriptRuntime?/g' "$BASE_PATH/Runtime/Values/JavaScriptBigInt.swift"
fi

# Fix JavaScriptFunction.swift
if [ -f "$BASE_PATH/Runtime/Values/JavaScriptFunction.swift" ]; then
  echo "Fixing JavaScriptFunction.swift..."
  sed -i '' 's/private weak let runtime: JavaScriptRuntime?/private weak var runtime: JavaScriptRuntime?/g' "$BASE_PATH/Runtime/Values/JavaScriptFunction.swift"
fi

# Fix JavaScriptObject.swift
if [ -f "$BASE_PATH/Runtime/Values/JavaScriptObject.swift" ]; then
  echo "Fixing JavaScriptObject.swift..."
  sed -i '' 's/private weak let runtime: JavaScriptRuntime?/private weak var runtime: JavaScriptRuntime?/g' "$BASE_PATH/Runtime/Values/JavaScriptObject.swift"
fi

# Fix JavaScriptPropNameID.swift
if [ -f "$BASE_PATH/Runtime/JavaScriptPropNameID.swift" ]; then
  echo "Fixing JavaScriptPropNameID.swift..."
  sed -i '' 's/weak let runtime: JavaScriptRuntime?/weak var runtime: JavaScriptRuntime?/g' "$BASE_PATH/Runtime/JavaScriptPropNameID.swift"
fi

# Fix JavaScriptTypedArray.swift
if [ -f "$BASE_PATH/Runtime/Values/JavaScriptTypedArray.swift" ]; then
  echo "Fixing JavaScriptTypedArray.swift..."
  sed -i '' 's/private weak let runtime: JavaScriptRuntime?/private weak var runtime: JavaScriptRuntime?/g' "$BASE_PATH/Runtime/Values/JavaScriptTypedArray.swift"
fi

# Fix JavaScriptValue.swift
if [ -f "$BASE_PATH/Runtime/Values/JavaScriptValue.swift" ]; then
  echo "Fixing JavaScriptValue.swift..."
  sed -i '' 's/private weak let runtime: JavaScriptRuntime?/private weak var runtime: JavaScriptRuntime?/g' "$BASE_PATH/Runtime/Values/JavaScriptValue.swift"
fi

# Fix JavaScriptWeakObject.swift
if [ -f "$BASE_PATH/Runtime/Values/JavaScriptWeakObject.swift" ]; then
  echo "Fixing JavaScriptWeakObject.swift..."
  sed -i '' 's/private weak let runtime: JavaScriptRuntime?/private weak var runtime: JavaScriptRuntime?/g' "$BASE_PATH/Runtime/Values/JavaScriptWeakObject.swift"
fi

echo "Done! All files have been patched."
echo ""
echo "Now run: npx patch-package expo-modules-jsi"
echo "This will create a patch file to persist these changes."
